// Electron 43 renderer -> main transport-only adapter. electron.remote.require() is
// intentionally retained here; it is not a PDF hosting/targeting mechanism.
const ELECTRON_REMOTE_REQUIRE_CONTRACT_VERSION = '0.1';
function createElectronRemoteRequireAdapter({ electronModule }) {
  function getCapabilities() {
    const remote=electronModule&&electronModule.remote;
    return {
      remoteAvailable:!!remote,
      requireFunction:typeof remote?.require==='function'
    };
  }
  function requireInMain(modulePath) {
    const target=String(modulePath||'').trim();
    if(!target) return {ok:false,modulePath:null,module:null,reason:'missing-module-path',error:'Main-process modulsti mangler'};
    const remote=electronModule&&electronModule.remote;
    if(!remote||typeof remote.require!=='function') return {ok:false,modulePath:target,module:null,reason:'remote-require-unavailable',error:"require('electron').remote.require er ikke tilgjengelig"};
    try { return {ok:true,modulePath:target,module:remote.require(target),reason:'exact-remote-require',error:null}; }
    catch(error){ return {ok:false,modulePath:target,module:null,reason:'remote-require-failed',error:error instanceof Error?error.message:String(error)}; }
  }
  return Object.freeze({contractVersion:ELECTRON_REMOTE_REQUIRE_CONTRACT_VERSION,getCapabilities,requireInMain});
}

const ELECTRON_FOCUS_DIAGNOSTICS_CONTRACT_VERSION = '0.4';

function createElectronFocusDiagnosticsAdapter({ mainModuleLoader }) {
  let resolved = null;

  function resolveBoundary() {
    if (resolved) return resolved;
    if (!mainModuleLoader || typeof mainModuleLoader.requireInMain !== 'function') {
      resolved = {ok:false,webContents:null,app:null,reason:'main-module-loader-unavailable',error:'Renderer-to-main module loader er ikke tilgjengelig'};
      return resolved;
    }
    const loaded = mainModuleLoader.requireInMain('electron');
    if (!loaded?.ok) {
      resolved = {ok:false,webContents:null,app:null,reason:loaded?.reason || 'main-electron-load-failed',error:loaded?.error || 'Kunne ikke laste Electron main-modulen'};
      return resolved;
    }
    const mainElectron = loaded.module || null;
    const webContents = mainElectron?.webContents || null;
    const app = mainElectron?.app || null;
    if (!webContents || typeof webContents.getAllWebContents !== 'function') {
      resolved = {ok:false,webContents:null,app,reason:'webcontents-unavailable',error:'Electron main-process webContents.getAllWebContents() er ikke tilgjengelig via main-transport'};
      return resolved;
    }
    resolved = {ok:true,webContents,app,reason:'main-transport-electron-module',error:null};
    return resolved;
  }

  function getAllWebContents() {
    const boundary=resolveBoundary();
    if(!boundary.ok) throw new Error(boundary.error || boundary.reason);
    return boundary.webContents.getAllWebContents() || [];
  }

  function getFocusedWebContents() {
    const boundary=resolveBoundary();
    if(!boundary.ok) throw new Error(boundary.error || boundary.reason);
    if(typeof boundary.webContents.getFocusedWebContents!=='function') throw new Error('Electron main-process webContents.getFocusedWebContents() er ikke tilgjengelig via main-transport');
    return boundary.webContents.getFocusedWebContents();
  }

  function describeFocusedFrame(wc) {
    try {
      const frame = wc && wc.focusedFrame;
      if (!frame) return null;
      const main = wc.mainFrame;
      const out = { isMainFrame: !!(main && frame === main) };
      for (const key of ['url', 'name', 'routingId', 'processId']) {
        try {
          const value = frame[key];
          if (value !== undefined && value !== null && value !== '') out[key] = value;
        } catch (_) {}
      }
      return out;
    } catch (error) {
      return { error:error instanceof Error ? error.message : String(error) };
    }
  }

  function onWebContentsCreated(callback) {
    if(typeof callback!=='function') throw new Error('web-contents-created callback mangler');
    const boundary=resolveBoundary();
    if(!boundary.ok) throw new Error(boundary.error || boundary.reason);
    const app=boundary.app;
    if(!app || typeof app.on!=='function') return {ok:true,subscribed:false,dispose:()=>false,reason:'main-app-event-unavailable',error:null};
    const handler=(_event,wc)=>callback(wc);
    app.on('web-contents-created',handler);
    let active=true;
    const dispose=()=>{
      if(!active) return false;
      active=false;
      if(typeof app.removeListener==='function') app.removeListener('web-contents-created',handler);
      else if(typeof app.off==='function') app.off('web-contents-created',handler);
      return true;
    };
    return {ok:true,subscribed:true,dispose,reason:'main-app-web-contents-created',error:null};
  }

  return Object.freeze({contractVersion:ELECTRON_FOCUS_DIAGNOSTICS_CONTRACT_VERSION,resolveBoundary,getAllWebContents,getFocusedWebContents,describeFocusedFrame,onWebContentsCreated});
}

const MAIN_PROCESS_TRANSPORT_CONTRACT_VERSION = '0.3';
const MAIN_PROCESS_TRANSPORT_KIND = 'electron-remote-require';
const REQUIRED_MAIN_BRIDGE_METHODS = Object.freeze([
  'install',
  'uninstall',
  'getState',
  'getPlatformCapabilities',
  'setRendererMenuOpen',
  'setKeyboardSelection',
  'clearKeyboardSelection',
  'reportKeyboardSelectionResult',
  'showLinkLocator',
  'setActivePdfIdentity',
  'focusPdfRuntime',
  'ensurePdfRuntime',
  'setIncludeHeaderFooterText',
  'chooseEmailImportSource',
  'printControlledEmailHtmlToPdf',
  'resolveEmailAttachmentPdfPoint'
]);

function createMainProcessTransport({ remoteRequireAdapter }) {
  let bridge = null;
  let modulePath = null;
  let lastLoad = null;

  function apiStatus(target = bridge) {
    const methods = {};
    for (const name of REQUIRED_MAIN_BRIDGE_METHODS) methods[name] = typeof target?.[name] === 'function';
    return {
      complete: REQUIRED_MAIN_BRIDGE_METHODS.every(name => methods[name]),
      methods
    };
  }

  function getCapabilities() {
    let remote = null;
    try { remote = remoteRequireAdapter?.getCapabilities?.() || null; } catch (_) {}
    return {
      contractVersion: MAIN_PROCESS_TRANSPORT_CONTRACT_VERSION,
      kind: MAIN_PROCESS_TRANSPORT_KIND,
      loaded: !!bridge,
      modulePath,
      loadBoundaryAvailable: remote?.requireFunction === true,
      remoteRequire: remote,
      api: apiStatus(),
      lastLoad
    };
  }

  function loadExact(exactModulePath) {
    const target = String(exactModulePath || '').trim();
    const rec = {
      ok: false,
      kind: MAIN_PROCESS_TRANSPORT_KIND,
      modulePath: target || null,
      reason: null,
      error: null,
      api: null
    };
    bridge = null;
    modulePath = null;
    if (!target) {
      rec.reason = 'missing-module-path';
      rec.error = 'Main-process bridge-sti mangler';
      lastLoad = rec;
      return rec;
    }
    if (!remoteRequireAdapter || typeof remoteRequireAdapter.requireInMain !== 'function') {
      rec.reason = 'transport-load-boundary-unavailable';
      rec.error = 'Renderer-to-main load boundary er ikke tilgjengelig';
      lastLoad = rec;
      return rec;
    }
    const loaded = remoteRequireAdapter.requireInMain(target);
    if (!loaded?.ok) {
      rec.reason = loaded?.reason || 'bridge-load-failed';
      rec.error = loaded?.error || rec.reason;
      lastLoad = rec;
      return rec;
    }
    const candidate = loaded.module;
    rec.api = apiStatus(candidate);
    if (!rec.api.complete) {
      rec.reason = 'bridge-api-incomplete';
      rec.error = 'main-bridge.js eksponerer ikke forventet API';
      lastLoad = rec;
      return rec;
    }
    bridge = candidate;
    modulePath = target;
    rec.ok = true;
    rec.reason = loaded?.reason || 'loaded';
    lastLoad = rec;
    return rec;
  }

  function reset() {
    bridge = null;
    modulePath = null;
    return getCapabilities();
  }

  function requireMethod(name) {
    if (!bridge) throw new Error('Main-process transport er ikke lastet');
    const fn = bridge[name];
    if (typeof fn !== 'function') throw new Error(`Main-process bridge mangler ${name}()`);
    return fn;
  }

  function invoke(name, ...args) {
    return requireMethod(name).apply(bridge, args);
  }

  return Object.freeze({
    contractVersion: MAIN_PROCESS_TRANSPORT_CONTRACT_VERSION,
    kind: MAIN_PROCESS_TRANSPORT_KIND,
    requiredMethods: REQUIRED_MAIN_BRIDGE_METHODS,
    getCapabilities,
    loadExact,
    reset,
    install: (...args) => invoke('install', ...args),
    uninstall: (...args) => invoke('uninstall', ...args),
    getState: (...args) => invoke('getState', ...args),
    getPlatformCapabilities: (...args) => invoke('getPlatformCapabilities', ...args),
    setRendererMenuOpen: (...args) => invoke('setRendererMenuOpen', ...args),
    setKeyboardSelection: (...args) => invoke('setKeyboardSelection', ...args),
    clearKeyboardSelection: (...args) => invoke('clearKeyboardSelection', ...args),
    reportKeyboardSelectionResult: (...args) => invoke('reportKeyboardSelectionResult', ...args),
    showLinkLocator: (...args) => invoke('showLinkLocator', ...args),
    setActivePdfIdentity: (...args) => invoke('setActivePdfIdentity', ...args),
    focusPdfRuntime: (...args) => invoke('focusPdfRuntime', ...args),
    ensurePdfRuntime: (...args) => invoke('ensurePdfRuntime', ...args),
    setIncludeHeaderFooterText: (...args) => invoke('setIncludeHeaderFooterText', ...args),
    chooseEmailImportSource: (...args) => invoke('chooseEmailImportSource', ...args),
    printControlledEmailHtmlToPdf: (...args) => invoke('printControlledEmailHtmlToPdf', ...args),
    resolveEmailAttachmentPdfPoint: (...args) => invoke('resolveEmailAttachmentPdfPoint', ...args)
  });
}

